import authPlugin from './plugins/auth.js';

// Module routes
import authRoutes from './modules/auth/auth.routes.js';
import peopleRoutes from './modules/people/people.routes.js';
import projectsRoutes from './modules/projects/projects.routes.js';
import conversationsRoutes from './modules/conversations/conversations.routes.js';
import requirementsRoutes from './modules/requirements/requirements.routes.js';
import milestonesRoutes from './modules/milestones/milestones.routes.js';
import collaboratorsRoutes from './modules/collaborators/collaborators.routes.js';
import plansRoutes from './modules/plans/plans.routes.js';
import filesRoutes from './modules/files/files.routes.js';
import dashboardRoutes from './modules/dashboard/dashboard.routes.js';

export async function buildApp() {
  const app = Fastify({ logger: true });

  // Error handler
  app.setErrorHandler(errorHandler);

  // CORS
  await app.register(cors, { origin: true });

  // JWT
  await app.register(jwt, { secret: config.jwtSecret });

  // Auth decorator
  await app.register(authPlugin);

  // Routes
  await app.register(authRoutes, { prefix: '/api/auth' });
  await app.register(peopleRoutes, { prefix: '/api/people' });
  await app.register(projectsRoutes, { prefix: '/api/projects' });
  await app.register(conversationsRoutes, { prefix: '/api/projects' });
  await app.register(requirementsRoutes, { prefix: '/api/projects' });
  await app.register(milestonesRoutes, { prefix: '/api/projects' });
  await app.register(collaboratorsRoutes, { prefix: '/api/projects' });
  await app.register(plansRoutes, { prefix: '/api/projects' });
  await app.register(filesRoutes, { prefix: '/api/projects' });
  await app.register(dashboardRoutes, { prefix: '/api/dashboard' });

  // Health check
  app.get('/health', async () => ({ status: 'ok', service: 'ensoria-os' }));

  return app;
}

import { prisma } from '../../lib/prisma.js';
import { NotFoundError, ValidationError } from '../../lib/errors.js';
import type { CreatePeopleBody, UpdatePeopleBody } from './people.schema.js';
import { PEOPLE_STAGES } from './people.schema.js';

export async function list(query: { type?: string; stage?: string; search?: string }) {
  const where: Record<string, unknown> = {};
  if (query.type) where.type = query.type;
  if (query.stage) where.stage = query.stage;
  if (query.search) {
    where.OR = [
      { name: { contains: query.search } },
      { email: { contains: query.search } },
      { company: { contains: query.search } },
    ];
  }
  return prisma.people.findMany({ where, orderBy: { createdAt: 'desc' } });
}

export async function getById(id: string) {
  const person = await prisma.people.findUnique({
    where: { id },
    include: { projects: true },
  });
  if (!person) throw new NotFoundError('People');
  return person;
}

export async function create(data: CreatePeopleBody) {
  return prisma.people.create({ data });
}

export async function update(id: string, data: UpdatePeopleBody) {
  await getById(id);
  return prisma.people.update({ where: { id }, data });
}

export async function changeStage(id: string, stage: string) {
  if (!PEOPLE_STAGES.includes(stage as typeof PEOPLE_STAGES[number])) {
    throw new ValidationError(`Invalid stage. Must be one of: ${PEOPLE_STAGES.join(', ')}`);
  }
  await getById(id);
  const updated = await prisma.people.update({ where: { id }, data: { stage } });
  await prisma.activity.create({
    data: {
      peopleId: id,
      type: 'stage_changed',
      description: `Stage changed to ${stage}`,
      metadata: JSON.stringify({ newStage: stage }),
    },
  });
  return updated;
}

export async function remove(id: string) {
  await getById(id);
  await prisma.people.delete({ where: { id } });
  return { success: true };
}

import { create } from 'zustand'
import { post, get, setToken, removeToken, getStoredToken } from '../lib/api'

export interface User {
  id: string
  email: string
  name: string
  role: string
  createdAt?: string
}

interface AuthState {
  user: User | null
  token: string | null
  isLoading: boolean
  isAuthenticated: boolean
  login: (email: string, password: string) => Promise<void>
  register: (email: string, password: string, name: string) => Promise<void>
  logout: () => void
  checkAuth: () => Promise<void>
}

export const useAuthStore = create<AuthState>((set) => ({
  user: null,
  token: getStoredToken(),
  isLoading: true,
  isAuthenticated: false,

  login: async (email, password) => {
    const data = await post<{ user: User; token: string }>('/auth/login', { email, password })
    setToken(data.token)
    set({ user: data.user, token: data.token, isAuthenticated: true })
  },

  register: async (email, password, name) => {
    const data = await post<{ user: User; token: string }>('/auth/register', { email, password, name })
    setToken(data.token)
    set({ user: data.user, token: data.token, isAuthenticated: true })
  },

  logout: () => {
    removeToken()
    set({ user: null, token: null, isAuthenticated: false })
  },

  checkAuth: async () => {
    const token = getStoredToken()
    if (!token) {
      set({ isLoading: false, isAuthenticated: false })
      return
    }
    try {
      const resp = await get<{ user: User }>('/auth/me')
      set({ user: resp.user, token, isAuthenticated: true, isLoading: false })
    } catch {
      removeToken()
      set({ user: null, token: null, isAuthenticated: false, isLoading: false })
    }
  },
}))

const API_BASE = '/api';

function getToken(): string | null {
  return localStorage.getItem('ensoria_token');
}

export function setToken(token: string) {
  localStorage.setItem('ensoria_token', token);
}

export function removeToken() {
  localStorage.removeItem('ensoria_token');
}

export function getStoredToken(): string | null {
  return getToken();
}

export function isAuthenticated(): boolean {
  return !!getToken();
}

async function request<T>(path: string, options: RequestInit = {}): Promise<T> {
  const token = getToken();
  const headers: Record<string, string> = {
    'Content-Type': 'application/json',
    ...((options.headers as Record<string, string>) || {}),
  };
  if (token) headers['Authorization'] = `Bearer ${token}`;

  const res = await fetch(`${API_BASE}${path}`, { ...options, headers });
  const json = await res.json();

  if (!res.ok) {
    const err = json.error || { code: 'UNKNOWN', message: 'Request failed' };
    throw new Error(err.message);
  }

  return json.data;
}

export function get<T>(path: string): Promise<T> {
  return request<T>(path);
}

export function post<T>(path: string, body: unknown): Promise<T> {
  return request<T>(path, { method: 'POST', body: JSON.stringify(body) });
}

export function put<T>(path: string, body: unknown): Promise<T> {
  return request<T>(path, { method: 'PUT', body: JSON.stringify(body) });
}

export function patch<T>(path: string, body: unknown): Promise<T> {
  return request<T>(path, { method: 'PATCH', body: JSON.stringify(body) });
}

export function del<T>(path: string): Promise<T> {
  return request<T>(path, { method: 'DELETE' });
}

