  { label: 'Contact', value: 'Contact' },
  { label: 'Opportunity', value: 'Opportunity' },
  { label: 'Client', value: 'Client' },
  { label: 'Recurring Client', value: 'Recurring Client' },
]

export default function PeoplePage() {
  const [search, setSearch] = useState('')
  const [typeFilter, setTypeFilter] = useState('')
  const [stageFilter, setStageFilter] = useState('')
  const [showDialog, setShowDialog] = useState(false)
  const [editPerson, setEditPerson] = useState<People | null>(null)
  const navigate = useNavigate()

  const { data: people, isLoading, error } = usePeople({ type: typeFilter || undefined, stage: stageFilter || undefined, search: search || undefined })
  const createMutation = useCreatePeople()
  const updateMutation = useUpdatePeople()
  const deleteMutation = useDeletePeople()
  const stageMutation = useChangePeopleStage()

  const handleSave = async (formData: Partial<People>) => {
    if (editPerson) {
      await updateMutation.mutateAsync({ id: editPerson.id, ...formData })
    } else {
      await createMutation.mutateAsync(formData)
    }
    setShowDialog(false)
    setEditPerson(null)
  }

  const handleDelete = async (id: string) => {
    if (confirm('Delete this person?')) await deleteMutation.mutateAsync(id)
  }

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <h1 className="text-xl font-bold text-[#e4e4ec]">People</h1>
        <Button onClick={() => { setEditPerson(null); setShowDialog(true) }}>+ Add Person</Button>
      </div>

      <div className="flex gap-3">
        <Input
          placeholder="Search people..."
          value={search}
          onChange={(e) => setSearch(e.target.value)}
          className="max-w-xs"
        />
        <Select value={typeFilter} onChange={setTypeFilter} options={typeOptions} className="w-36" />
        <Select value={stageFilter} onChange={setStageFilter} options={stageOptions} className="w-44" />
      </div>

      {isLoading && <LoadingSpinner />}
      {error && <ErrorMessage />}
      {people && people.length === 0 && <EmptyState message="No people found" />}

      {people && people.length > 0 && (
        <Table>
          <TableHeader>
            <TableRow>
              <TableHead>Name</TableHead>
              <TableHead>Type</TableHead>
              <TableHead>Stage</TableHead>
              <TableHead>Email</TableHead>
              <TableHead>Company</TableHead>
              <TableHead>Actions</TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {people.map((p) => (
              <TableRow key={p.id}>
                <TableCell>
                  <button className="text-violet-400 hover:underline" onClick={() => navigate(`/people/${p.id}`)}>
                    {p.name}
                  </button>
                </TableCell>
                <TableCell><span className="text-xs text-[#9898b0] capitalize">{p.type}</span></TableCell>
                <TableCell>
                  <Select
                    value={p.stage}
                    onChange={(stage) => stageMutation.mutate({ id: p.id, stage })}
                    options={[
                      { label: 'Contact', value: 'Contact' },
                      { label: 'Opportunity', value: 'Opportunity' },
                      { label: 'Client', value: 'Client' },
                      { label: 'Recurring Client', value: 'Recurring Client' },
                    ]}
                    className="w-36"
                  />
                </TableCell>
                <TableCell className="text-[#9898b0]">{p.email || '—'}</TableCell>
                <TableCell className="text-[#9898b0]">{p.company || '—'}</TableCell>
                <TableCell>
                  <div className="flex gap-2">
                    <Button
                      variant="ghost"
                      size="sm"
                      onClick={() => { setEditPerson(p); setShowDialog(true) }}
                    >
                      Edit
                    </Button>
                    <Button variant="danger" size="sm" onClick={() => handleDelete(p.id)}>Delete</Button>
                  </div>
                </TableCell>
              </TableRow>
            ))}
          </TableBody>
        </Table>
      )}

      <PeopleFormDialog
        open={showDialog}
        onClose={() => { setShowDialog(false); setEditPerson(null) }}
        onSave={handleSave}
        person={editPerson}
        loading={createMutation.isPending || updateMutation.isPending}
      />
    </div>
  )
}

function PeopleFormDialog({
  open, onClose, onSave, person, loading,
}: {
  open: boolean
  onClose: () => void
  onSave: (data: Partial<People>) => void
  person: People | null
  loading: boolean
}) {
  const [name, setName] = useState(person?.name || '')
  const [type, setType] = useState(person?.type || 'client')
  const [email, setEmail] = useState(person?.email || '')
  const [phone, setPhone] = useState(person?.phone || '')
  const [company, setCompany] = useState(person?.company || '')
  const [stage, setStage] = useState(person?.stage || 'Contact')

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault()
    onSave({ name, type, email: email || null, phone: phone || null, company: company || null, stage })
  }

  return (
    <Dialog open={open} onClose={onClose} title={person ? 'Edit Person' : 'Add Person'}>
      <form onSubmit={handleSubmit} className="space-y-3">
        <Input placeholder="Name" value={name} onChange={(e) => setName(e.target.value)} required />
        <Select value={type} onChange={setType} options={[
          { label: 'Staff', value: 'staff' }, { label: 'Partner', value: 'partner' },
          { label: 'Freelancer', value: 'freelancer' }, { label: 'Company', value: 'company' },
          { label: 'Investor', value: 'investor' },
        ]} />
        <Input placeholder="Email" type="email" value={email} onChange={(e) => setEmail(e.target.value)} />
        <Input placeholder="Phone" value={phone} onChange={(e) => setPhone(e.target.value)} />
        <Input placeholder="Company" value={company} onChange={(e) => setCompany(e.target.value)} />
        <Select value={stage} onChange={setStage} options={[
          { label: 'Contact', value: 'Contact' }, { label: 'Opportunity', value: 'Opportunity' },
          { label: 'Client', value: 'Client' }, { label: 'Recurring Client', value: 'Recurring Client' },
        ]} />
        <div className="flex justify-end gap-2 pt-2">
          <Button type="button" variant="outline" onClick={onClose}>Cancel</Button>
          <Button type="submit" disabled={loading}>
            {loading ? 'Saving...' : person ? 'Update' : 'Create'}
          </Button>
        </div>
      </form>
    </Dialog>
  )
}

import type { FastifyInstance } from 'fastify';
import { RegisterBody, LoginBody } from './auth.schema.js';
import * as authService from './auth.service.js';
import { prisma } from '../../lib/prisma.js';

export default async function authRoutes(fastify: FastifyInstance) {
  fastify.post('/register', async (request, reply) => {
    const body = RegisterBody.parse(request.body);
    const user = await authService.register(body);
    const token = fastify.jwt.sign({ userId: user.id, email: user.email, role: user.role });
    return reply.status(201).send({ data: { user, token } });
  });

  fastify.post('/login', async (request) => {
    const body = LoginBody.parse(request.body);
    const user = await authService.login(body);
    const token = fastify.jwt.sign({ userId: user.id, email: user.email, role: user.role });
    return { data: { user, token } };
  });

  fastify.get('/me', { onRequest: [fastify.authenticate] }, async (request) => {
    const user = await prisma.user.findUnique({
      where: { id: request.user!.userId },
      select: { id: true, email: true, name: true, role: true, createdAt: true },
    });
    return { data: { user } };
  });
}

import { prisma } from '../../lib/prisma.js';
import { NotFoundError, ValidationError } from '../../lib/errors.js';
import type { CreateProjectBody, UpdateProjectBody } from './projects.schema.js';
import { PROJECT_STAGES } from './projects.schema.js';

export async function list(query: { stage?: string; peopleId?: string; search?: string }) {
  const where: Record<string, unknown> = {};
  if (query.stage) where.stage = query.stage;
  if (query.peopleId) where.peopleId = query.peopleId;
  if (query.search) {
    where.OR = [
      { name: { contains: query.search } },
      { description: { contains: query.search } },
    ];
  }
  return prisma.project.findMany({
    where,
    include: { people: true, conversations: true },
    orderBy: { createdAt: 'desc' },
  });
}

export async function getById(id: string) {
  const project = await prisma.project.findUnique({
    where: { id },
    include: {
      people: true,
      conversations: { orderBy: { createdAt: 'desc' } },
      files: true,
      requirements: { orderBy: { createdAt: 'desc' } },
      milestones: { orderBy: { createdAt: 'desc' } },
      collaborators: true,
      plans: { orderBy: { createdAt: 'desc' } },
      analytics: { orderBy: { generatedAt: 'desc' } },
    },
  });
  if (!project) throw new NotFoundError('Project');
  return project;
}

export async function create(data: CreateProjectBody) {
  const project = await prisma.project.create({ data });
  if (data.peopleId) {
    await prisma.activity.create({
      data: {
        peopleId: data.peopleId,
        projectId: project.id,
        type: 'created',
        description: `Project "${data.name}" created`,
        metadata: JSON.stringify({ stage: data.stage }),
      },
    });
  }
  return project;
}

export async function update(id: string, data: UpdateProjectBody) {
  await getById(id);
  return prisma.project.update({ where: { id }, data });
}

export async function changeStage(id: string, stage: string) {
  if (!PROJECT_STAGES.includes(stage as typeof PROJECT_STAGES[number])) {
    throw new ValidationError(`Invalid stage. Must be one of: ${PROJECT_STAGES.join(', ')}`);
  }
  await getById(id);
  const updated = await prisma.project.update({ where: { id }, data: { stage } });
  await prisma.activity.create({
    data: {
      projectId: id,
      type: 'stage_changed',
      description: `Project stage changed to ${stage}`,
      metadata: JSON.stringify({ newStage: stage }),
    },
  });
  return updated;
}

export async function remove(id: string) {
  await getById(id);
  await prisma.project.delete({ where: { id } });
  return { success: true };
}

import React, { useEffect } from 'react'
import { useNavigate, useLocation, Outlet } from 'react-router-dom'
import { useAuthStore } from '../../stores/authStore'
import { Sidebar } from './Sidebar'
import { Header } from './Header'
import { LoadingSpinner } from '../shared/LoadingSpinner'

export function ProtectedRoute() {
  const { isAuthenticated, isLoading, checkAuth } = useAuthStore()
  const navigate = useNavigate()

  useEffect(() => {
    checkAuth()
  }, [checkAuth])

  useEffect(() => {
    if (!isLoading && !isAuthenticated) navigate('/login', { replace: true })
  }, [isLoading, isAuthenticated, navigate])

  if (isLoading) return <LoadingSpinner size="lg" />
  if (!isAuthenticated) return null

  return <Outlet />
}

export function AppLayout() {
  const navigate = useNavigate()
  const location = useLocation()
  const { user, logout } = useAuthStore()

  const handleNavigate = (path: string) => navigate(path)
  const handleLogout = () => { logout(); navigate('/login') }

  return (
    <div className="flex h-screen bg-[#0a0a0f]">
      <Sidebar currentPath={location.pathname} onNavigate={handleNavigate} />
      <div className="flex-1 flex flex-col overflow-hidden">
        <Header userName={user?.name || 'User'} onLogout={handleLogout} />
        <main className="flex-1 overflow-auto p-6">
          <Outlet />
        </main>
      </div>
    </div>
  )
}

import React, { useState } from 'react'
import { useNavigate } from 'react-router-dom'
import { useProjects, useCreateProject, useChangeProjectStage, useDeleteProject } from '../hooks/useProjects'
import { usePeople } from '../hooks/usePeople'
import { Button } from '../components/ui/button'
import { Input } from '../components/ui/input'
import { Select } from '../components/ui/select'
import { Dialog } from '../components/ui/dialog'
import { LoadingSpinner } from '../components/shared/LoadingSpinner'
import { EmptyState } from '../components/shared/EmptyState'
import { ErrorMessage } from '../components/shared/ErrorMessage'

const stageColors: Record<string, string> = {
  Contact: 'border-t-blue-500',
  Opportunity: 'border-t-amber-500',
  Proposal: 'border-t-violet-500',
  Implementation: 'border-t-cyan-500',
  Onboarding: 'border-t-green-500',
  Live: 'border-t-emerald-500',
  Validated: 'border-t-purple-500',
}

const stageBadgeColors: Record<string, string> = {
  Contact: 'bg-blue-500/20 text-blue-300',
  Opportunity: 'bg-amber-500/20 text-amber-300',
  Proposal: 'bg-violet-500/20 text-violet-300',
  Implementation: 'bg-cyan-500/20 text-cyan-300',
  Onboarding: 'bg-green-500/20 text-green-300',
  Live: 'bg-emerald-500/20 text-emerald-300',
  Validated: 'bg-purple-500/20 text-purple-300',
}

const stageOrder = ['Contact', 'Opportunity', 'Proposal', 'Implementation', 'Onboarding', 'Live', 'Validated']

export default function ProjectsPage() {
  const [showDialog, setShowDialog] = useState(false)
  const navigate = useNavigate()

  const { data: projects, isLoading, error } = useProjects()
  const { data: people } = usePeople()
  const createMutation = useCreateProject()
  const stageMutation = useChangeProjectStage()
  const deleteMutation = useDeleteProject()

  const peopleByName = new Map((people || []).map((p) => [p.id, p.name]))

  const groupedProjects: Record<string, any[]> = {}
  for (const p of (projects || [])) {
    if (!groupedProjects[p.stage]) groupedProjects[p.stage] = []
    groupedProjects[p.stage].push(p)
  }

  const handleDelete = async (id: string) => {
    if (confirm('Delete this project?')) await deleteMutation.mutateAsync(id)
  }

  if (isLoading) return <LoadingSpinner size="lg" />
  if (error) return <ErrorMessage />

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <h1 className="text-xl font-bold text-[#e4e4ec]">Projects</h1>
        <Button onClick={() => setShowDialog(true)}>+ New Project</Button>
      </div>

      {(!projects || projects.length === 0) && <EmptyState message="No projects yet" />}

      <div className="flex gap-4 overflow-x-auto pb-4" style={{ minHeight: 400 }}>
        {stageOrder.map((stage) => {
          const stageProjects = groupedProjects[stage] || []
          return (
            <div key={stage} className="min-w-[240px] flex-shrink-0">
              <div className="flex items-center justify-between mb-3 px-1">
                <span className={`text-xs font-semibold uppercase px-2 py-1 rounded ${stageBadgeColors[stage] || ''}`}>
                  {stage}
                </span>
                <span className="text-xs text-[#9898b0]">{stageProjects.length}</span>
              </div>
              <div className="space-y-2">
                {stageProjects.map((p) => (
                  <div
                    key={p.id}
                    className={`bg-[#1a1a24] rounded-lg border border-[#2a2a3a] border-t-2 ${stageColors[p.stage] || ''} p-3 cursor-pointer hover:border-violet-500/50 transition-colors`}
                    onClick={() => navigate(`/projects/${p.id}`)}
                  >
                    <p className="text-sm font-medium text-[#e4e4ec] truncate">{p.name}</p>
                    <p className="text-xs text-[#9898b0] mt-1">{peopleByName.get(p.peopleId) || '—'}</p>
                    <div className="flex items-center justify-between mt-2">
                      {p.value != null && (
                        <span className="text-xs font-medium text-green-400">€{p.value.toLocaleString()}</span>
                      )}
                      <Button
                        variant="ghost"
                        size="sm"
                        className="ml-auto"
                        onClick={(e) => { e.stopPropagation(); handleDelete(p.id) }}
                      >
                        🗑️
                      </Button>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )
        })}
      </div>

      <ProjectFormDialog
        open={showDialog}
        onClose={() => setShowDialog(false)}
        people={people || []}
        onSave={async (data) => {
          await createMutation.mutateAsync(data)
          setShowDialog(false)
        }}
        loading={createMutation.isPending}
      />
    </div>
  )
}

function ProjectFormDialog({
  open, onClose, people, onSave, loading,
}: {
  open: boolean
  onClose: () => void
  people: { id: string; name: string }[]
  onSave: (data: { name: string; peopleId: string; value?: number | null; stage?: string }) => void
  loading: boolean
}) {
  const [name, setName] = useState('')
  const [peopleId, setPeopleId] = useState(people[0]?.id || '')
  const [value, setValue] = useState('')
  const [stage, setStage] = useState('Contact')

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault()
    onSave({ name, peopleId, value: value ? parseFloat(value) : null, stage })
  }

  return (
    <Dialog open={open} onClose={onClose} title="New Project">
      <form onSubmit={handleSubmit} className="space-y-3">
        <Input placeholder="Project name" value={name} onChange={(e) => setName(e.target.value)} required />
        <Select value={peopleId} onChange={setPeopleId} options={people.map((p) => ({ label: p.name, value: p.id }))} />
        <Input placeholder="Value (€)" type="number" value={value} onChange={(e) => setValue(e.target.value)} />
        <Select value={stage} onChange={setStage} options={stageOrder.map((s) => ({ label: s, value: s }))} />
        <div className="flex justify-end gap-2 pt-2">
          <Button type="button" variant="outline" onClick={onClose}>Cancel</Button>
          <Button type="submit" disabled={loading}>Create</Button>
        </div>
      </form>
    </Dialog>
  )
}

import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query'
import { get, post, put, patch, del } from '../lib/api'

export interface Project {
  id: string
  name: string
  description?: string | null
  stage: string
  value?: number | null
  peopleId: string
  people?: { id: string; name: string; company?: string | null }
  createdAt: string
  updatedAt: string
  conversations?: unknown[]
  requirements?: unknown[]
  milestones?: unknown[]
  collaborators?: unknown[]
  plans?: unknown[]
  files?: unknown[]
  analytics?: unknown[]
}

export function useProjects(filters?: { stage?: string; peopleId?: string; search?: string }) {
  const params = new URLSearchParams()
  if (filters?.stage) params.set('stage', filters.stage)
  if (filters?.peopleId) params.set('peopleId', filters.peopleId)
  if (filters?.search) params.set('search', filters.search)
  const qs = params.toString()

  return useQuery({
    queryKey: ['projects', filters],
    queryFn: () => get<Project[]>(`/projects${qs ? `?${qs}` : ''}`),
  })
}

export function useProject(id: string) {
  return useQuery({
    queryKey: ['projects', id],
    queryFn: () => get<Project>(`/projects/${id}`),
    enabled: !!id,
  })
}

export function useCreateProject() {
  const qc = useQueryClient()
  return useMutation({
    mutationFn: (body: Partial<Project>) => post<Project>('/projects', body),
    onSuccess: () => qc.invalidateQueries({ queryKey: ['projects'] }),
  })
}

export function useUpdateProject() {
  const qc = useQueryClient()
  return useMutation({
    mutationFn: ({ id, ...body }: Partial<Project> & { id: string }) =>
      put<Project>(`/projects/${id}`, body),
    onSuccess: () => { qc.invalidateQueries({ queryKey: ['projects'] }) },
  })
}

export function useDeleteProject() {
  const qc = useQueryClient()
  return useMutation({
    mutationFn: (id: string) => del(`/projects/${id}`),
    onSuccess: () => qc.invalidateQueries({ queryKey: ['projects'] }),
  })
}

export function useChangeProjectStage() {
  const qc = useQueryClient()
  return useMutation({
    mutationFn: ({ id, stage }: { id: string; stage: string }) =>
      patch<Project>(`/projects/${id}/stage`, { stage }),
    onSuccess: () => { qc.invalidateQueries({ queryKey: ['projects'] }) },
  })
}

