  --color-bg-main: #0a0a0f;
  --color-bg-surface: #13131a;
  --color-bg-surface-2: #1a1a24;
  --color-border: #2a2a3a;
  --color-text-primary: #e4e4ec;
  --color-text-secondary: #9898b0;
  --color-accent: #a78bfa;
  --color-accent-2: #7c3aed;
  --color-green: #34d399;
  --color-amber: #fbbf24;
  --color-rose: #f87171;
  --color-blue: #60a5fa;
}

body {
  margin: 0;
  background-color: #0a0a0f;
  color: #e4e4ec;
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Inter', sans-serif;
}

* {
  box-sizing: border-box;
}

export interface JwtPayload {
  userId: string;
  email: string;
  role: string;
}

declare module 'fastify' {
  interface FastifyInstance {
    authenticate: (request: FastifyRequest, reply: FastifyReply) => Promise<void>;
  }
  interface FastifyRequest {
    user?: JwtPayload;
  }
}

import { z } from 'zod/v4';

export const CreatePeopleBody = z.object({
  type: z.enum(['staff', 'partner', 'freelancer', 'company', 'investor']).default('client'),
  name: z.string().min(1),
  email: z.string().email().optional().nullable(),
  phone: z.string().optional().nullable(),
  company: z.string().optional().nullable(),
  stage: z.string().default('Contact'),
  notes: z.string().optional().nullable(),
  tags: z.string().default(''),
});

export const UpdatePeopleBody = CreatePeopleBody.partial();

export const StageChangeBody = z.object({
  stage: z.enum(['Contact', 'Opportunity', 'Client', 'Recurring Client']),
});

export const PeopleQuery = z.object({
  type: z.string().optional(),
  stage: z.string().optional(),
  search: z.string().optional(),
});

export const PEOPLE_STAGES = ['Contact', 'Opportunity', 'Client', 'Recurring Client'] as const;

export type CreatePeopleBody = z.infer<typeof CreatePeopleBody>;
export type UpdatePeopleBody = z.infer<typeof UpdatePeopleBody>;

import fp from 'fastify-plugin';
import type { FastifyInstance, FastifyRequest, FastifyReply } from 'fastify';
import type { JwtPayload } from '../types/index.js';
import { UnauthorizedError } from '../lib/errors.js';

export default fp(async function authPlugin(fastify: FastifyInstance) {
  fastify.decorate('authenticate', async function (request: FastifyRequest, _reply: FastifyReply) {
    try {
      await request.jwtVerify<JwtPayload>();
    } catch {
      throw new UnauthorizedError();
    }
  });
});

